export const MOCAP_BONE_COUNT = 19;

function decodeFloat32(base64) {
  if (typeof atob === 'function') {
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    return new Float32Array(bytes.buffer);
  }
  const buf = Buffer.from(base64, 'base64');
  return new Float32Array(buf.buffer, buf.byteOffset, buf.byteLength / 4);
}

export const MOCAP_CLIPS = Object.create(null);
export const MOCAP_CLIP_META = Object.create(null);
for (const raw of CLIP_DATA) {
  const clip = {
    name: raw.name, loop: raw.loop, fps: raw.fps,
    frameCount: raw.frameCount, duration: raw.duration,
    quats: decodeFloat32(raw.quats),
    hips: decodeFloat32(raw.hips),
  };
  MOCAP_CLIPS[clip.name] = clip;
  MOCAP_CLIP_META[clip.name] = {
    name: clip.name, loop: clip.loop, duration: clip.duration,
    frameCount: clip.frameCount, fps: clip.fps,
  };
}

export function mocapClip(name) {
  return MOCAP_CLIPS[name] || null;
}
